  p=urllib.parse.urlparse(self.path); q=urllib.parse.parse_qs(p.query); x=p.path.split('/')
  if p.path=='/api/health': return self.sendj(200,{'status':'ok','node_id':int(os.environ.get('NODE_ID','0'))})
