    try:c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],b['name'],int(bool(b.get('is_private'))),b.get('topic',''))); cid=c.lastrowid;c.execute('INSERT INTO cmembers VALUES(?,?)',(cid,u['id']));c.execute('INSERT INTO counters VALUES(?,0)',(cid,));c.commit();return self.sendj(201,{'channel':channel(c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone())})
    except sqlite3.IntegrityError:return self.sendj(409,{'error':'duplicate'})
   if len(x)==5 and x[1:3]==['api','channels'] and x[4]=='join':
