    if not body:return self.sendj(400,{'error':'empty'})
    parent=b.get('parent_id'); mentions=[]
    for name in re.findall(r'(?<![\w])@([A-Za-z0-9_-]+)',body):
     z=c.execute('SELECT id FROM users WHERE username=?',(name,)).fetchone()
     if z and z['id']!=u['id'] and member(c,cid,z['id']):mentions.append(z['id'])
    mentions=list(dict.fromkeys(mentions)); c.execute('BEGIN IMMEDIATE'); c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at,mentions) VALUES(?,?,?,?,?,?)',(cid,u['id'],body,parent,now(),json.dumps(mentions))); mid=c.lastrowid; r=c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone(); frame=emit(c,cid,'message.reply' if parent else 'message.created',{'message':msgobj(c,r)});c.commit();broadcast(frame);return self.sendj(201,{'message':msgobj(c,r)})
   if p.path=='/api/dms':
