    if not ch:c.execute('INSERT INTO channels(name,is_dm) VALUES(?,1)',(f'dm-{a}-{bid}',));cid=c.lastrowid;c.execute('INSERT INTO cmembers VALUES(?,?),(?,?)',(cid,a,cid,bid));c.execute('INSERT INTO counters VALUES(?,0)',(cid,));c.commit()
