    c.commit(); nu=c.execute('SELECT * FROM users WHERE id=?',(u['id'],)).fetchone(); return self.sendj(200,{'user':obju(nu)})
   if self.path.startswith('/api/messages/'):
    mid=self.path.split('/')[3]; r=c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone()
    if not r:return self.sendj(404,{'error':'not found'})
    if r['author_id']!=u['id']:return self.sendj(403,{'error':'forbidden'})
    c.execute('UPDATE messages SET body=?,edited_at=? WHERE id=?',(b.get('body',''),now(),mid));c.commit();return self.sendj(200,{'message':msgobj(c,c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone())})
   return self.sendj(404,{'error':'not found'})
  finally:c.close()
 def register(self):
  b=self.body()
