   c.execute('INSERT INTO users(username,password,display_name,timezone,avatar_url,status_text,status_emoji) VALUES(?,?,?,?,?,?,?)',(b['username'],hashlib.sha256(b['password'].encode()).hexdigest(),b.get('display_name',b['username']),'UTC','','',''));uid=c.lastrowid;t=secrets.token_urlsafe(24);c.execute('INSERT INTO tokens VALUES(?,?)',(t,uid));c.commit();return self.sendj(201,{'user':obju(c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()),'token':t})
