    if j.get('type')=='subscribe':
     ch=j['channel_id']; sockets[-1]=(self.connection,ch); c=db();head=c.execute('SELECT n FROM counters WHERE channel_id=?',(ch,)).fetchone();c.close();ws_send(self.connection,{'type':'subscribed','channel_id':ch,'head_event_id':head['n'] if head else 0})
    elif j.get('type')=='resume':
     c=db();rs=c.execute('SELECT message FROM events WHERE channel_id=? AND event_id>? ORDER BY event_id',(j['channel_id'],j.get('since_event_id',0)));[ws_send(self.connection,json.loads(r['message'])) for r in rs];head=c.execute('SELECT n FROM counters WHERE channel_id=?',(j['channel_id'],)).fetchone();c.close();ws_send(self.connection,{'type':'resumed','channel_id':j['channel_id'],'head_event_id':head['n'] if head else 0})
  except:pass
