 def ui(self):
  html='''<!doctype html><html><head><meta charset=utf-8><title>Huddle</title><style>body{margin:0;font:14px Arial;background:#fff}button{border:0;padding:9px;color:#fff;background:#1264a3}button[data-button-role=primary]{background:#007a5a}button[data-button-role=danger]{background:#e01e5a}.layout{display:flex;height:100vh}.side{width:240px;background:#3f0e40;color:white;padding:20px}.main{padding:25px;flex:1}</style></head><body><div id=app><form data-testid=auth-form id=auth-form><input name=username placeholder=username><input name=password type=password placeholder=password><button data-testid=auth-submit data-button-role=primary>Login</button></form><div class=layout style=display:none><aside class=side><h2 data-testid=workspace-header>Huddle</h2><div data-testid=channel-list></div><button data-testid=new-channel-btn>New channel</button><button data-testid=logout-btn data-button-role=danger>Logout</button></aside><main class=main><h2 data-testid=channel-title>#general</h2><div data-testid=channel-topic></div><div data-testid=message-list></div><input data-testid=message-input><button data-testid=send-btn data-button-role=primary>Send</button></main></div></div><script>const $=s=>document.querySelector(s);let t=localStorage.getItem("huddle.token");if(t)load();$("#auth-form").onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);let r=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(f))});let j=await r.json();if(r.ok){localStorage.setItem("huddle.token",j.token);load()}};async function load(){ $("#auth-form").style.display="none";document.querySelector(".layout").style.display="flex";let r=await fetch("/api/workspaces",{headers:{Authorization:"Bearer "+(t||localStorage.getItem("huddle.token"))}});let j=await r.json();if(j.workspaces?.[0]){$("[data-testid=workspace-header]").textContent=j.workspaces[0].name;}};$("#logout-btn").onclick=()=>{localStorage.removeItem("huddle.token");location.reload()};</script></body></html>'''
