cat > /app/start.sh <<'SH'
#!/bin/bash
set -u
echo $$ >/tmp/start.pid
mkdir -p /app/data
redis-server --bind 127.0.0.1 --port 6379 --save '' --appendonly no >/tmp/redis.log 2>&1 & R=$!
pids=()
for i in 0 1 2; do python3 /app/app.py $((8000+i)) >/tmp/node$i.log 2>&1 & pids+=($!); done
