```mswea_bash_command
cat > /app/irc.py <<'PY'
import socket,threading,sys,os
sys.path.insert(0,'/app')
from app import user
SERVER='huddle'
nicks=set(); lock=threading.Lock()
def send(c,text):
 try:c.sendall((':'+SERVER+' '+text+'\r\n').encode())
 except:pass
def client(c,addr):
 token=None; nick=None; registered=False
 try:
  buf=b''
  while True:
   data=c.recv(4096)
   if not data:break
   buf+=data
   while b'\n' in buf:
    raw,buf=buf.split(b'\n',1); line=raw.rstrip(b'\r').decode(errors='replace')
    if not line:continue
    parts=line.split(' ',1); cmd=parts[0].upper(); rest=parts[1] if len(parts)>1 else ''
    if cmd=='PASS':
     token=rest.strip()
     if not user(token):
      send(c,'464 * :Password incorrect')
      token=None
    elif cmd=='NICK':
     candidate=rest.split()[0] if rest else ''
     with lock: busy=candidate in nicks
     if busy:
      send(c,'433 * '+candidate+' :Nickname is already in use')
      continue
     if nick:
      with lock:nicks.discard(nick)
     nick=candidate
     with lock:nicks.add(nick)
    elif cmd=='USER':
     if not token or not user(token):
      send(c,'464 '+(nick or '*')+' :Password incorrect'); continue
     if not registered and nick:
      registered=True
      for num,text in [('001','Welcome to Huddle'),('002','Your host is huddle'),('003','This server was created locally'),('004','huddle 1.0 oiwsz biklmnop'),('005','CHANTYPES=# PREFIX=(ov)@+ :are supported'),('422',':MOTD File is missing')]:
       send(c,num+' '+nick+' :'+text)
    elif cmd=='PING':
     val=rest[1:] if rest.startswith(':') else rest
     send(c,'PONG '+SERVER+' :'+val)
    elif cmd=='QUIT':
     return
    elif cmd in ('NAMES','WHO','LIST','TOPIC','MODE','PONG'):
     if cmd!='PONG': send(c,'421 '+(nick or '*')+' '+cmd+' :Accepted')
    else:
     send(c,'421 '+(nick or '*')+' '+cmd+' :Unknown command')
 finally:
  if nick:
   with lock:nicks.discard(nick)
  try:c.close()
  except:pass
def main():
 s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind(('0.0.0.0',6667));s.listen(100)
 while True:
  c,a=s.accept();threading.Thread(target=client,args=(c,a),daemon=True).start()
if __name__=='__main__':main()
